// End-to-end structured output contract over the real queue, turn, delivery and persistence.
// Responses below are raw JSON; no legacy test-fixture adapter participates.
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { config } from "../src/config.js";
import { runAs } from "../src/context.js";
import { loadChat, saveChat } from "../src/memory.js";
import { previewParts, renderParts } from "../src/girls/template.js";
import { riley } from "../src/girls/riley.js";
import { M, turnRig, installModelStub, restoreFetch, mkItem } from "./lib/turn-rig.js";

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "structured-turn-"));
const dirs = { data: config.dataDir, logs: config.logDir };
config.dataDir = path.join(dir, "data"); config.logDir = path.join(dir, "logs");
let cases = 0;
installModelStub(); M.rawStructured = true;
try {
  for (const route of [{}, { bcid: "structured-business" }]) {
    for (const selection of ["photo 1", "photo 2", "free photo", "none"]) {
      const rig = turnRig("simulated");
      const before = M.requests;
      M.reply = JSON.stringify({ selection, reply: selection === "none" ? "hello there" : "here is the photo" });
      let downloaded = "";
      (rig.deps as any).download = async (item: { key: string }) => { downloaded = item.key; return Buffer.from("fake"); };
      // Ordinary chat retains the full optional-offer contract. The scoped required
      // generic-photo contract is covered by check-shared-photo-repair.ts.
      await rig.fan(901, "how was your day", route);
      const row = rig.rows().at(-1);
      assert.equal(M.requests - before, 1); assert.equal(row.raw, M.reply); assert.equal(row.selection, selection);
      assert.equal(M.bodies.at(-1).response_format.json_schema.name, "twin_reply");
      const choices = M.bodies.at(-1).response_format.json_schema.schema.properties.selection.enum;
      assert.deepEqual(choices, ["none", ...row.menu.map((x: any) => x.slot)]);
      assert(row.system.includes("Return one JSON object: selection first, then reply."));
      assert(!row.system.includes("put its exact tag at the end of your reply"));
      if (selection === "none") {
        assert.equal(row.selectedMedia, null); assert.equal(row.delivery.media, undefined);
        assert.equal(rig.tg.texts.at(-1), "hello there");
      } else {
        const expected = row.menu.find((x: any) => x.slot === selection).key;
        assert.equal(row.selectedMedia.key, expected); assert.equal(downloaded, expected);
        assert.equal(row.media.key, expected); assert.equal(row.delivery.media.status, "acknowledged");
        assert.equal(rig.tg.of(selection.startsWith("free") ? "sendPhoto" : "sendPaidMedia").length, 1);
        assert(runAs(rig.slug, () => loadChat(901)).sent.includes(expected));
      }
      assert(rig.tg.calls.every(c => c.payload.business_connection_id === route.bcid));
      assert(!row.final.join(" ").includes("selection"));
      rig.stop(); cases++;
    }
    for (const raw of [
      'plain text [photo 1]',
      '{"selection":"photo 999","reply":"here"}',
      '{"reply":"here"}',
      '{"selection":"photo 1","reply":"here","extra":"field"}',
      JSON.stringify({selection:"none",reply:"here [photo 1]"}),
      JSON.stringify({selection:"photo 1",reply:"here [photo 2]"}),
      JSON.stringify({selection:"photo 1",reply:"here\n[locked photo waiting for him to unlock: A smiling selfie in a hoodie.]"}),
      JSON.stringify({selection:"none",reply:"hello [tip"}),
      JSON.stringify({selection:"none",reply:"[locked photo waiting for him to unlock: blue dress]"}),
    ]) {
      const rig = turnRig("simulated"), before = M.requests;
      M.reply = raw; await rig.fan(902, "show me a photo", route);
      const row = rig.rows().at(-1);
      assert.equal(M.requests - before, 1, "bad structured result must not cause semantic retry");
      assert.equal(row.selectedMedia, null); assert.equal(row.delivery.media, undefined);
      assert.equal(rig.tg.of("sendPaidMedia").length + rig.tg.of("sendPhoto").length, 0);
      assert(row.delivery.fixedLine, "contract failure keeps non-billable fixed-line classification");
      assert.equal(row.raw, raw); assert(!row.final.join(" ").includes("["));
      rig.stop(); cases++;
    }
    {
      const rig = turnRig("simulated");
      M.reply = JSON.stringify({selection:"photo 1", reply:"YOUR CONTENT READY TO SEND"});
      await rig.fan(904, "send me a photo", route);
      const row = rig.rows().at(-1);
      assert.equal(row.media.key, row.menu.find((x:any)=>x.slot==="photo 1").key);
      assert.equal(row.delivery.media.status,"acknowledged");
      assert(!row.final.join(" ").includes("CONTENT READY"));
      rig.stop(); cases++;
    }
    // A repeated previously sent item cannot re-enter the enum or dispatch via a saved slot.
    const rig = turnRig("simulated");
    runAs(rig.slug, () => saveChat(903, {ageConfirmed:true,epoch:0,history:[],sent:rig.deps.catalogue.map(x=>x.key)}));
    M.reply = JSON.stringify({selection:"photo 1",reply:"here is the photo"});
    await rig.fan(903, "send that same photo again", route);
    assert.deepEqual(M.bodies.at(-1).response_format.json_schema.schema.properties.selection.enum, ["none"]);
    assert.equal(rig.rows().at(-1).selectedMedia, null);
    rig.stop(); cases++;
  }
  {
    // Saved Cat Chase replay failure: the validated structured choice was photo 3,
    // while reply prose copied the legacy delivery note for that same file. The
    // duplicate marker is stripped; it cannot cancel the already validated card.
    const rig = turnRig("simulated", "structured-cat-note");
    const photos = [
      mkItem("photo", "11111111-1111-4111-8111-111111111111", "A person takes a mirror selfie wearing denim shorts.", { star_value: 700 }),
      mkItem("photo", "22222222-2222-4222-8222-222222222222", "A person poses in black lingerie in front of a mirror.", { star_value: 800 }),
      mkItem("photo", "33333333-3333-4333-8333-333333333333", "A person sits on a bed with orange bedding, wearing a multicolored sweater.", { star_value: 700 }),
    ];
    (rig.deps as any).catalogue = photos;
    const oldRandom = Math.random, oldStarPrice = process.env.STAR_PRICE;
    Math.random = () => 0; process.env.STAR_PRICE = "real";
    try {
      M.reply = JSON.stringify({selection:"photo 3", reply:"ok here u go, me chilling on the bed in my fave sweater\n[locked photo waiting for him to unlock: A person sits on a bed with orange bedding, wearing a multicolored sweater.]"});
      await rig.fan(905, "Actually, can you send me a new photo now?", { bcid: "structured-cat-business" });
    } finally {
      Math.random = oldRandom;
      if (oldStarPrice === undefined) delete process.env.STAR_PRICE; else process.env.STAR_PRICE = oldStarPrice;
    }
    const row = rig.rows().at(-1), paid = rig.tg.of("sendPaidMedia");
    assert.equal(row.selection, "photo 3"); assert.equal(row.selectionError, undefined);
    assert.equal(row.selectedMedia.key, photos[2].key); assert.equal(row.media.key, photos[2].key);
    assert.equal(row.delivery.media.status, "acknowledged"); assert.equal(paid.length, 1);
    assert.equal(paid[0].payload.star_count, 700);
    assert.equal(paid[0].payload.caption, "ok here u go, me chilling on the bed in my fave sweater");
    assert(!row.final.join(" ").includes("[locked photo"));
    rig.stop(); cases++;
  }
  const rendered = renderParts(riley.vars), displayed = previewParts(riley.vars);
  assert.equal(JSON.stringify(displayed), JSON.stringify(rendered), "display uses the same shared contract");
  console.log(`PASS ${cases} structured pipeline cases; both routes, raw responses, exact files, no sends on invalid output`);
} finally {
  M.rawStructured = false; restoreFetch(); config.dataDir = dirs.data; config.logDir = dirs.logs;
  fs.rmSync(dir, {recursive:true,force:true});
}

