  };
  const parts: { text: string; v?: string }[] = [];
  let last = 0;
  for (const m of TEMPLATE.matchAll(/\{\{([A-Z_]+)\}\}/g)) {
    if (m.index! > last) parts.push({ text: TEMPLATE.slice(last, m.index) });
    const k = m[1];
