    return `${ALT_NOTE}${miss.length ? ` (does not show: ${miss.join(", ")})` : ""}: `;
  };
  m.photos.forEach((it, i) => lines.push(`[photo ${i + 1}] (locked): ${alt(it)}${describe(it)}`));
  if (m.video) lines.push(`[video 1] (locked): ${alt(m.video)}${describe(m.video)}`);
  if (m.bundle) lines.push(`[bundle 1] (locked): ${m.bundle.desc}`);
  if (m.free) lines.push(`[free ${m.free.kind}] (${m.reference?.owned ? "already owned, resend unlocked" : "free"}): ${alt(m.free)}${describe(m.free)}`);
  if (!lines.length) return m.reference ? `YOUR CONTENT READY TO SEND${prior}\n(none available for this request, so don't offer any)`
    : `YOUR CONTENT READY TO SEND${available}\n(${a ? "no eligible items ready to send now" : "no content listed for this turn"}, so don't offer any)`;
  const altHint = m.alt?.size ? ` (A line marked "${ALT_NOTE.split(",")[0]}" is not an exact match. Photo captions are labelled as alternatives automatically; explain video or bundle alternatives in your own words; never write the marker words or "does not show" to him.)` : "";
